#[inline]
pub unsafe fn ZopfliInitCache(
    mut blocksize: size_t,
    mut lmc: *mut ZopfliLongestMatchCache,
) {
    let lmc_view: &mut ZopfliLongestMatchCache = unsafe { &mut *lmc }; // SAFETY: caller provided a valid, writable pointer to ZopfliLongestMatchCache.

    let ushort_bytes =
        (::core::mem::size_of::<c_ushort>() as size_t).wrapping_mul(blocksize);
    let sublen_bytes =
        ((ZOPFLI_CACHE_LENGTH * 3 as c_int) as size_t).wrapping_mul(blocksize);

    lmc_view.length = malloc(ushort_bytes) as *mut c_ushort;
    lmc_view.dist = malloc(ushort_bytes) as *mut c_ushort;
    lmc_view.sublen = malloc(sublen_bytes) as *mut c_uchar;

    if lmc_view.sublen.is_null() {
        fprintf(
            stderr,
            b"Error: Out of memory. Tried allocating %lu bytes of memory.\n\0" as *const u8
                as *const c_char,
            (ZOPFLI_CACHE_LENGTH as size_t)
                .wrapping_mul(3 as size_t)
                .wrapping_mul(blocksize),
        );
        exit(EXIT_FAILURE);
    }

    if !lmc_view.dist.is_null() && blocksize != 0 {
        unsafe { ::core::ptr::write_bytes(lmc_view.dist, 0, blocksize) }; // SAFETY: dist points to an allocation of at least blocksize c_ushort elements when non-null.
    }

    if !lmc_view.sublen.is_null() && sublen_bytes != 0 {
        unsafe { ::core::ptr::write_bytes(lmc_view.sublen, 0, sublen_bytes) }; // SAFETY: sublen points to an allocation of at least sublen_bytes bytes when non-null.
    }

    if !lmc_view.length.is_null() && blocksize != 0 {
        let mut i: size_t = 0;
        while i < blocksize {
            unsafe { *lmc_view.length.add(i) = 1 as c_ushort }; // SAFETY: length points to an allocation of at least blocksize c_ushort elements when non-null; i is in-bounds.
            i = i.wrapping_add(1);
        }
    }
}

